/* @lc app=leetcode id=3585 lang=kotlin */ class Solution { fun lca(up: Array<IntArray>, dep: IntArray, a0: Int, b0: Int): Int = (if (dep[a0] >= dep[b0]) a0 to b0 else b0 to a0).let { (a, b) -> (0 until 17).fold(a) { x, k -> if ((dep[a] - dep[b]) shr k and 1 == 1) up[k][x] else x }.let { a1 -> if (a1 == b) a1 else (16 downTo 0).fold(a1 to b) { (x, y), k -> if (up[k][x] != up[k][y]) up[k][x] to up[k][y] else x to y }.let { (x, _) -> up[0][x] } } } fun findMedian(n: Int, edges: Array<IntArray>, queries: Array<IntArray>): IntArray = edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> IntArray(n).let { dep -> LongArray(n).let { ds -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { (v, _) -> par[v] == -1 }.onEach { (v, w) -> par.set(v, u).also { dep[v] = dep[u] + 1 }.also { ds[v] = ds[u] + w } }.map { it.first } }.takeIf { it.isNotEmpty() } }.count().let { Array(17) { IntArray(n) }.also { up -> par.copyInto(up[0]) }.also { up -> (1 until 17).forEach { k -> (0 until n).forEach { v -> up[k][v] = up[k - 1][up[k - 1][v]] } } }.let { up -> queries.map { (u, v) -> lca(up, dep, u, v).let { l -> (ds[u] + ds[v] - 2 * ds[l]).let { D -> if (2 * (ds[u] - ds[l]) >= D) (16 downTo 0).fold(u) { x, k -> up[k][x].let { y -> if (dep[y] >= dep[l] && 2 * (ds[u] - ds[y]) < D) y else x } }.let { x -> if (2 * (ds[u] - ds[x]) >= D) x else up[0][x] } else (16 downTo 0).fold(v) { x, k -> up[k][x].let { y -> if (dep[y] >= dep[l] && 2 * (ds[v] - ds[y]) <= D) y else x } } } } }.toIntArray() } } } } } } }